from pathlib import Path
import re,html,difflib,markdown,json
O=Path(__file__).resolve().parent;R=O.parents[3]
def render(s):return markdown.markdown(re.sub(r'<!--\s*@[^>]*-->','',s),extensions=['extra','sane_lists'])
def image(n,c):return '<figure><a href="'+n+'.png"><img loading="lazy" src="'+n+'.png" alt="'+html.escape(c,quote=True)+'"></a><figcaption>'+c+'</figcaption></figure>'
before=(O/'Color_Rainbow.before.md').read_text(encoding='utf-8');after=(R/'commons/maps/Color_Rainbow/final.md').read_text(encoding='utf-8');assert after==(O/'Color_Rainbow.after.md').read_text(encoding='utf-8')
a=before.split('\n\n');b=after.split('\n\n');pairs=[]
for tag,i,j,k,l in difflib.SequenceMatcher(None,a,b,autojunk=False).get_opcodes():
 if tag=='equal':continue
 pairs.append('<div class="pair"><div><h3>Before</h3>'+(render('\n\n'.join(a[i:j])) or '<p>Added shared illustration.</p>')+'</div><div><h3>Now</h3>'+render('\n\n'.join(b[k:l]))+'</div></div>')
css=re.search(r'<style>(.*?)</style>',(O.parent/'2026-09-23-array-molnar-volume/index.html').read_text(encoding='utf-8'),re.S)[1]
page='<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Rainbow — room for another colour</title><style>'+css+'</style></head><body><main>'
page+='''<div class="eyebrow">Ada Research · Colour · 23 September 2026</div><h1>Room for another colour.</h1><p class="intro">The arch keeps its opening.<br>What else could it welcome?</p><p class="status">Applied to <strong>Color_Rainbow/final.md</strong>. The mature chapter remains, with one scale correction and a shared illustration from the working museum.</p><nav><a href="#encounter">The celebration</a><a href="#arrangements">Four arrangements</a><a href="#comparison">What changed</a><a href="#reading">Read the chapter</a><a href="#evidence">Evidence</a><a href="/compose/sources?map=Color_Rainbow&amp;doc=final">Read and comment</a></nav>'''
page+='<section id="encounter"><h2>You have not solved a puzzle yet</h2>'+image('celebration','The existing celebration in the actual museum, captured with its confetti. Stars, dressed mushrooms, optional steps and a level path surround the same rainbow generator.')+'<p>This chapter already moves from welcome to a particular question: a familiar form can hold another arrangement, while its four available presets still leave choices unmade. That movement is worth keeping.</p><details><summary>Colours already welcome elsewhere in the hall</summary>'+image('dressed-mushrooms','Pearl collars and coloured caps, as placed in the hall.')+image('banners','The striped banners include pale, white and dark colours absent from the arch’s saturated HSV sweep.')+'</details></section>'
page+='<section id="arrangements"><h2>A division can move without closing the passage</h2>'+image('four-arrangements','RE-DIVIDE, operated through the actual button, produces six, seven, forty-eight and two bands. The camera stays fixed. The selected palette also reaches the steps and pavers; their transforms remain unchanged.')+'<p>The native mesh measurements give the same 1.288-metre total band thickness and 6.9-metre opening for all four choices. The prose previously called the unscaled generator width of 5.6 units “metres”. The display scale matters here.</p>'+image('under-the-arch','Looking back from the walker’s reached position, with a 1.65-metre eye-height offset. The ordinary controller crossed beneath the arch on the level centre path and returned through the welcome volume.')+'</section>'
page+='<section id="comparison"><h2>A small correction; a visible comparison</h2><p>The opening, celebration, four-choice limit, HSV explanation, code excerpts, collision distinction and next-hall question remain. One paragraph now distinguishes the generator’s width from the scaled hall display. The new figure uses the same four states the visitor can choose.</p>'+''.join(pairs)+'<p><a href="Color_Rainbow.diff">Exact manuscript diff</a> · <a href="source-changes.diff">Companion changes</a></p></section>'
page+='<section id="reading"><article class="reading">'+render(after)+'</article></section>'
page+='''<section id="evidence" class="evidence"><h2>What was checked</h2><p>40 focused assertions pass in an isolated run of the production museum: actual pointer press/release callbacks, all four partitions, fixed world-space dimensions and route transforms, the arch’s absence of collision, eight collidable steps, repeatable confetti using the same 96 instances, and its configured expiry.</p><p>Supplied key input drove the ordinary museum controller down the centre path, through the welcome trigger, beneath the arch and back. Arrival and return both triggered the existing celebration. This verifies the selected desktop route, not every possible path or physical reach in a headset.</p><p>Four-arrangement captures suppress confetti for comparison; the celebration view shows its native simulation at a selected time. Figures resize and label native Godot captures. No generated imagery stands in for the artifact.</p><p>No production source, map, control or sequence change was needed. No tracked-controller, headset comfort, learner or performance claim; no live museum restart, live bake/save overwrite, commit or frozen book/audio rebuild.</p><p><a href="report.json">Runtime record</a> · <a href="source_manifest.json">Capture inputs</a> · <a href="verification.json">Preservation and publication checks</a> · <a href="SUMMARY.md">Findings and decisions</a></p></section><footer>Next: Color_Pillar — a colour field has values between the bodies that sample it.</footer></main></body></html>'''
(O/'index.html').write_text(page,encoding='utf-8')
diffs=[]
for relative in json.loads((O/'baseline-hashes.json').read_text()):
 if relative.endswith('/final.md'):continue
 diffs.extend(difflib.unified_diff((O/'before'/relative).read_text(encoding='utf-8').splitlines(True),(R/relative).read_text(encoding='utf-8').splitlines(True),fromfile='before/'+relative,tofile=relative))
(O/'source-changes.diff').write_text(''.join(diffs),encoding='utf-8')
print('Built the current reading and exact comparison.')
